 async function saveUserPermissions(e:any){e.preventDefault();if(!supabase||!isAdmin||!selectedPatient)return;if(!editUserBranchIds.length){setError('اختار فرعًا واحدًا على الأقل للمستخدم.');return;}setBusy(true);const r=await supabase.from('profiles').update({branch_id:editUserBranchIds[0],permissions:{...(selectedPatient.permissions||{}),modules:Array.isArray(form.permissions?.modules)?form.permissions.modules:[]}}).eq('id',selectedPatient.id);if(r.error){setError(r.error.message);setBusy(false);return;}const del=await supabase.from('user_branch_access').delete().eq('user_id',selectedPatient.id);if(del.error){setError('تم تحديث صلاحيات الأقسام لكن تعذر تحديث الفروع: '+del.error.message);setBusy(false);return;}const ins=await supabase.from('user_branch_access').insert(editUserBranchIds.map(branch_id=>({user_id:selectedPatient.id,organization_id:org,branch_id})));if(ins.error){setError('تم تحديث صلاحيات الأقسام لكن تعذر حفظ الفروع: '+ins.error.message);setBusy(false);return;}setModal('');await refresh();setBusy(false);}
 async function getAdminAccessToken(){if(!supabase)return null;let current=await supabase.auth.getSession();let session=current.data.session;if(!session)return null;const exp=session.expires_at||0;if(exp*1000<Date.now()+60000){const refreshed=await supabase.auth.refreshSession();if(refreshed.error||!refreshed.data.session)return null;session=refreshed.data.session;}return session.access_token;}
 async function adminUsersRequest(method:'POST'|'PUT',body:any){let token=await getAdminAccessToken();if(!token)return {response:null,result:{error:'انتهت جلسة الدخول. سجل الدخول مرة أخرى وحاول.'}};let response=await fetch('/api/admin/users',{method,headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`},body:JSON.stringify(body)});let result=await response.json();if(response.status===401){token=await getAdminAccessToken();if(token){response=await fetch('/api/admin/users',{method,headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`},body:JSON.stringify(body)});result=await response.json();}}return {response,result};}
