 async function showPatientDetails(p:Row){
  setSelectedPatient(p);setModal('patient-details');setPatientTab('overview');setPatientPrivate(null);setPatientImages([]);setPatientVisits([]);setPatientAppointments([]);setPatientOperations([]);setPatientTransactions([]);
  if(!supabase)return;
  const canSeeFinance=['admin','finance'].includes(profile?.role);
  // Appointments and booking are Reception-only. Doctors get clinical visit history,
  // not appointment or booking records.
  const appointmentRequest=profile?.role==='doctor'
   ? Promise.resolve({data:[],error:null})
   : supabase.from('appointments').select('*').eq('patient_id',p.id).order('scheduled_at',{ascending:false});
  const requests:any[]=[
   supabase.from('patient_images').select('*').eq('patient_id',p.id).order('captured_at',{ascending:false}),
   supabase.from('visits').select('*').eq('patient_id',p.id).order('visited_at',{ascending:false}),
   appointmentRequest,
   supabase.from('operations_clinical').select('*').eq('patient_id',p.id).order('scheduled_at',{ascending:false}),
  ];
  if(['admin','reception'].includes(profile?.role))requests.push(supabase.from('patient_private_details').select('*').eq('patient_id',p.id).maybeSingle());
  if(canSeeFinance)requests.push(supabase.from('financial_transactions').select('*').eq('patient_id',p.id).order('paid_at',{ascending:false}));
  const results=await Promise.all(requests);const imageResult=results[0];const visitResult=results[1];const appointmentResult=results[2];const operationResult=results[3];
  setPatientVisits(visitResult.data||[]);setPatientAppointments(appointmentResult.data||[]);setPatientOperations(operationResult.data||[]);
  let idx=4;if(['admin','reception'].includes(profile?.role)){setPatientPrivate(results[idx]?.data||null);idx++;}if(canSeeFinance)setPatientTransactions(results[idx]?.data||[]);
  const signed=await Promise.all((imageResult.data||[]).map(async (i:Row)=>{const result=await supabase!.storage.from('clinic-patient-images').createSignedUrl(i.storage_path,3600);return {...i,url:result.data?.signedUrl||''};}));
  setPatientImages(signed);
 }
 async function savePatientVisit(e:any){e.preventDefault();if(!supabase||!selectedPatient||!org)return;setBusy(true);const result=await supabase.from('visits').insert({organization_id:org,branch_id:selectedPatient.branch_id||branchId,patient_id:selectedPatient.id,doctor_id:profile?.role==='doctor'?profile.id:null,visited_at:form.visited_at?new Date(form.visited_at).toISOString():new Date().toISOString(),complaint:form.complaint||null,diagnosis:form.diagnosis||null,examination:form.examination||null,treatment_plan:form.treatment_plan||null,prescription:form.prescription||null,notes:form.notes||null,created_by:profile?.id});if(result.error){setError(result.error.message);setBusy(false);return;}setBusy(false);setModal('patient-details');await showPatientDetails(selectedPatient);}
