function ModalActions({close,busy}:{close:()=>void;busy:boolean}){return <div className="modal-actions"><button type="button" className="cancel" onClick={close}>إلغاء</button><button type="submit" className="add-btn" disabled={busy}>{busy?'جارٍ الحفظ…':'حفظ'}</button></div>}
async function watermarkFile(file:File):Promise<File>{try{if(!file.type.startsWith('image/'))return file;const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;const ctx=canvas.getContext('2d');if(!ctx)return file;ctx.drawImage(bitmap,0,0);const logo=new Image();logo.src='/hair-clinic-logo.jpg';await new Promise<void>(resolve=>{logo.onload=()=>resolve();logo.onerror=()=>resolve();});const pad=Math.max(16,canvas.width*.02);const logoW=Math.min(canvas.width*.23,320);const logoH=logo.naturalWidth?logoW*(logo.naturalHeight/logo.naturalWidth):logoW*.5;if(logo.naturalWidth){ctx.globalAlpha=.55;ctx.drawImage(logo,canvas.width-logoW-pad,canvas.height-logoH-pad,logoW,logoH);ctx.globalAlpha=1;}else{ctx.fillStyle='rgba(255,255,255,.45)';ctx.font=`bold ${Math.max(14,canvas.width*.025)}px Arial`;ctx.fillText('DHC HAIR EXPERTS',canvas.width-pad-210,canvas.height-pad-12);}const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,file.type==='image/png'?'image/png':'image/jpeg',.92));if(!blob)return file;return new File([blob],file.name,{type:blob.type});}catch{return file;}}
